/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pump_video` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
